10440             // Push LayoutSelectableSpacing (which is LayoutItemSpacing minus hit-spacing, if we decide to have hit gaps between items)
10441             // Altering style ItemSpacing may seem unnecessary as we position every items using SetCursorScreenPos()...
10442             // But it is necessary for two reasons:
10443             // - Selectables uses it by default to visually fill the space between two items.
10444             // - The vertical spacing would be measured by Clipper to calculate line height if we didn't provide it explicitly (here we do).
10445             ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(LayoutSelectableSpacing, LayoutSelectableSpacing));
10446 
10447             // Rendering parameters
10448             const ImU32 icon_type_overlay_colors[3] = { 0, IM_COL32(200, 70, 70, 255), IM_COL32(70, 170, 70, 255) };
10449             const ImU32 icon_bg_color = ImGui::GetColorU32(ImGuiCol_MenuBarBg);
10450             const ImVec2 icon_type_overlay_size = ImVec2(4.0f, 4.0f);
10451             const bool display_label = (LayoutItemSize.x >= ImGui::CalcTextSize("999").x);
10452 
10453             const int column_count = LayoutColumnCount;
10454             ImGuiListClipper clipper;
