10559             // Zooming with CTRL+Wheel
10560             if (ImGui::IsWindowAppearing())
10561                 ZoomWheelAccum = 0.0f;
10562             if (ImGui::IsWindowHovered() && io.MouseWheel != 0.0f && ImGui::IsKeyDown(ImGuiMod_Ctrl) && ImGui::IsAnyItemActive() == false)
10563             {
10564                 ZoomWheelAccum += io.MouseWheel;
10565                 if (fabsf(ZoomWheelAccum) >= 1.0f)
10566                 {
10567                     // Calculate hovered item index from mouse location
10568                     // FIXME: Locking aiming on 'hovered_item_idx' (with a cool-down timer) would ensure zoom keeps on it.
10569                     const float hovered_item_nx = (io.MousePos.x - start_pos.x + LayoutItemSpacing * 0.5f) / LayoutItemStep.x;
10570                     const float hovered_item_ny = (io.MousePos.y - start_pos.y + LayoutItemSpacing * 0.5f) / LayoutItemStep.y;
10571                     const int hovered_item_idx = ((int)hovered_item_ny * LayoutColumnCount) + (int)hovered_item_nx;
10572                     //ImGui::SetTooltip("%f,%f -> item %d", hovered_item_nx, hovered_item_ny, hovered_item_idx); // Move those 4 lines in block above for easy debugging
10573 
10574                     // Zoom
10575                     IconSize *= powf(1.1f, (float)(int)ZoomWheelAccum);
10576                     IconSize = IM_CLAMP(IconSize, 16.0f, 128.0f);
10577                     ZoomWheelAccum -= (int)ZoomWheelAccum;
10578                     UpdateLayoutSizes(avail_width);
10579 
10580                     // Manipulate scroll to that we will land at the same Y location of currently hovered item.
10581                     // - Calculate next frame position of item under mouse
10582                     // - Set new scroll position to be used in next ImGui::BeginChild() call.
10583                     float hovered_item_rel_pos_y = ((float)(hovered_item_idx / LayoutColumnCount) + fmodf(hovered_item_ny, 1.0f)) * LayoutItemStep.y;
10584                     hovered_item_rel_pos_y += ImGui::GetStyle().WindowPadding.y;
10585                     float mouse_local_y = io.MousePos.y - ImGui::GetWindowPos().y;
10586                     ImGui::SetScrollY(hovered_item_rel_pos_y - mouse_local_y);
10587                 }
10588             }
