10304     {
10305         // Layout: when not stretching: allow extending into right-most spacing.
10306         LayoutItemSpacing = (float)IconSpacing;
10307         if (StretchSpacing == false)
10308             avail_width += floorf(LayoutItemSpacing * 0.5f);
10309 
10310         // Layout: calculate number of icon per line and number of lines
10311         LayoutItemSize = ImVec2(floorf(IconSize), floorf(IconSize));
10312         LayoutColumnCount = IM_MAX((int)(avail_width / (LayoutItemSize.x + LayoutItemSpacing)), 1);
10313         LayoutLineCount = (Items.Size + LayoutColumnCount - 1) / LayoutColumnCount;
10314 
10315         // Layout: when stretching: allocate remaining space to more spacing. Round before division, so item_spacing may be non-integer.
10316         if (StretchSpacing && LayoutColumnCount > 1)
10317             LayoutItemSpacing = floorf(avail_width - LayoutItemSize.x * LayoutColumnCount) / LayoutColumnCount;
10318 
10319         LayoutItemStep = ImVec2(LayoutItemSize.x + LayoutItemSpacing, LayoutItemSize.y + LayoutItemSpacing);
10320         LayoutSelectableSpacing = IM_MAX(floorf(LayoutItemSpacing) - IconHitSpacing, 0.0f);
10321         LayoutOuterPadding = floorf(LayoutItemSpacing * 0.5f);
